@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses. Find the right classes for your academic journey.</p>
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
    </div>

    <section class="mt-5">
        <h2>Departments</h2>
        <div class="row row-cols-1 row-cols-md-3 g-3 mt-2">
            @foreach (var dept in departments)
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text text-muted">@dept.Description</p>
                            <a href="/courses?department=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mt-5">
        <h2>Featured Courses</h2>
        <div class="row row-cols-1 row-cols-md-2 g-3 mt-2">
            @foreach (var course in featuredCourses)
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.DisplayCode — @course.Title</h5>
                            <p class="card-text">@course.Description</p>
                            <p class="card-text"><small class="text-muted">@course.Credits credits · @course.InstructorName</small></p>
                            <a href="/courses/@course.Id" class="btn btn-outline-secondary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<Department> departments = new();
    private List<Course> featuredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        featuredCourses = CatalogService.GetFeaturedCourses();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Courses — University Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="row mb-4 mt-3">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search courses, instructors..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="selectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name (@dept.Code)</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    @if (filteredCourses.Any())
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in filteredCourses)
                    {
                        <tr>
                            <td><strong>@course.DisplayCode</strong></td>
                            <td>@course.Title</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @filteredCourses.Count course(s)</p>
    }
    else
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? department { get; set; }

    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; FilterCourses(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; FilterCourses(); }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (department.HasValue)
            _selectedDepartmentId = department.Value;
        FilterCourses();
    }

    private void FilterCourses()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        string? search = string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm;
        filteredCourses = CatalogService.GetCourses(search, deptFilter);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        FilterCourses();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course") — University Course Catalog</PageTitle>

<div class="container">
    @if (course is null)
    {
        <div class="alert alert-warning">Course not found.</div>
        <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses?department=@course.DepartmentId">@course.DepartmentCode</a></li>
                <li class="breadcrumb-item active">@course.DisplayCode</li>
            </ol>
        </nav>

        <h1>@course.DisplayCode — @course.Title</h1>

        <div class="row mt-4">
            <div class="col-md-8">
                <h4>Description</h4>
                <p>@course.Description</p>

                <h4 class="mt-4">Schedule</h4>
                <p>@course.Schedule</p>

                <h4 class="mt-4">Credits</h4>
                <p><span class="badge bg-primary fs-6">@course.Credits credits</span></p>
            </div>
            <div class="col-md-4">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@course.InstructorName</h6>
                        <p class="card-text">@course.InstructorBio</p>
                    </div>
                </div>

                <div class="mt-3">
                    <a href="/enroll?courseId=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
                </div>
            </div>
        </div>

        <div class="mt-4">
            <a href="/courses" class="btn btn-outline-secondary">← Back to Catalog</a>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit a request to enroll in a course. You will receive confirmation via your university email.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@selectedCourseDisplay</strong> has been received. You will be notified of your enrollment status.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
            <AntiforgeryToken />
            <div class="row">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                               @bind="Model.StudentName" required />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                               @bind="Model.StudentId" required placeholder="e.g., S12345678" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <select class="form-select" id="courseSelect" name="Model.CourseId"
                                @bind="Model.CourseId" required>
                            <option value="0" disabled>Select a course...</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.DisplayCode — @course.Title (@course.Credits cr)</option>
                            }
                        </select>
                    </div>

                    <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </div>
            </div>
        </form>
    }
